cheatsheets.code:
SELECT name, price FROM products;
SELECT * FROM customers;
SELECT name AS title FROM products;

SELECT * FROM products WHERE price > 1000;
SELECT * FROM products WHERE stock = 0 AND price < 500;
SELECT * FROM products WHERE category <> 'Мебель';

SELECT name, price FROM products ORDER BY price DESC;
SELECT name, age FROM customers ORDER BY age, name;
SELECT * FROM products ORDER BY price ASC LIMIT 5;

SELECT COUNT(*) FROM products;
SELECT SUM(quantity) FROM orders;
SELECT AVG(price) FROM products;
SELECT MAX(price), MIN(price) FROM products;

SELECT c.name, p.name FROM orders o
JOIN customers c ON o.customer_id = c.id
JOIN products p ON o.product_id = p.id;

SELECT p.name, o.id FROM products p
LEFT JOIN orders o ON o.product_id = p.id
WHERE o.id IS NULL;

SELECT * FROM products WHERE name LIKE 'К%';
SELECT * FROM products WHERE price BETWEEN 300 AND 4000;
SELECT * FROM customers WHERE city IN ('Москва', 'Казань');

INSERT INTO products (name, category, price, stock)
VALUES ('Часы', 'Электроника', 5000, 10);
UPDATE products SET price = 5500 WHERE id = 11;
